    {
      "name": "数字特征",
      "aliases": ["numerical characteristics", "随机变量的数字特征"],
      "definition_snippet": "对分布的简化描述，包括期望、方差、协方差等",
      "category": "concept"
    },
    {
      "name": "数学期望",
      "aliases": ["expected value", "期望"],
      "definition_snippet": "随机变量的平均值，离散为Σxₖpₖ，连续为∫xf(x)dx",
      "category": "concept"
    },
    {
      "name": "离散型随机变量",
      "aliases": ["discrete random variable"],
      "definition_snippet": "取值可列的随机变量，期望用求和定义",
      "category": "concept"
    },
    {
      "name": "连续型随机变量",
      "aliases": ["continuous random variable"],
      "definition_snippet": "具有密度函数f(x)的随机变量，期望用积分定义",
      "category": "concept"
    },
    {
      "name": "随机变量函数的期望",
      "aliases": ["expectation of a function of a random variable"],
      "definition_snippet": "E(g(X))按分布用求和或积分计算",
      "category": "operation"
    },
    {
      "name": "期望的线性性",
      "aliases": ["linearity of expectation"],
      "definition_snippet": "E(aX+b)=aE(X)+b，E(X+Y)=E(X)+E(Y)",
      "category": "property"
    },
    {
      "name": "独立",
      "aliases": ["independence", "随机变量独立"],
      "definition_snippet": "随机变量之间相互独立，独立时E(XY)=E(X)E(Y)",
      "category": "concept"
    },
    {
      "name": "方差",
      "aliases": ["variance"],
      "definition_snippet": "D(X)=E[(X-E(X))²]=E(X²)-[E(X)]²，描述离散程度",
      "category": "concept"
    },
    {
      "name": "标准差",
      "aliases": ["standard deviation"],
      "definition_snippet": "σ=√D(X)",
      "category": "concept"
    },
    {
      "name": "方差的性质",
      "aliases": ["properties of variance"],
      "definition_snippet": "D(C)=0，D(aX+b)=a²D(X)，独立时D(X±Y)=D(X)+D(Y)",
      "category": "property"
    },
    {
      "name": "二项分布",
      "aliases": ["binomial distribution", "B(n, p)"],
      "definition_snippet": "X~B(n,p)，E(X)=np，D(X)=np(1-p)",
      "category": "concept"
    },
    {
      "name": "泊松分布",
      "aliases": ["Poisson distribution", "P(λ)"],
      "definition_snippet": "X~P(λ)，E(X)=λ，D(X)=λ",
      "category": "concept"
    },
    {
      "name": "均匀分布",
      "aliases": ["uniform distribution", "U(a, b)"],
      "definition_snippet": "X~U(a,b)，E(X)=(a+b)/2，D(X)=(b-a)²/12",
      "category": "concept"
    },
    {
      "name": "指数分布",
      "aliases": ["exponential distribution", "E(λ)"],
      "definition_snippet": "X~E(λ)，E(X)=1/λ，D(X)=1/λ²",
      "category": "concept"
    },
    {
      "name": "正态分布",
      "aliases": ["normal distribution", "N(μ, σ²)"],
      "definition_snippet": "X~N(μ,σ²)，E(X)=μ，D(X)=σ²",
      "category": "concept"
    },
    {
      "name": "协方差",
      "aliases": ["covariance"],
      "definition_snippet": "Cov(X,Y)=E(XY)-E(X)E(Y)，描述线性关联",
      "category": "concept"
    },
    {
      "name": "相关系数",
      "aliases": ["correlation coefficient", "ρ_{XY}"],
      "definition_snippet": "ρ_{XY}=Cov(X,Y)/(√D(X)√D(Y))，|ρ|≤1",
      "category": "concept"
    },
    {
      "name": "不相关",
      "aliases": ["uncorrelated"],
      "definition_snippet": "ρ=0称X与Y不相关",
      "category": "concept"
    },
    {
      "name": "原点矩",
      "aliases": ["raw moment", "k阶原点矩"],
      "definition_snippet": "E(X^k)称为X的k阶原点矩",
      "category": "concept"
    },
    {
      "name": "中心矩",
      "aliases": ["central moment", "k阶中心矩"],
      "definition_snippet": "E[(X-E(X))^k]称为k阶中心矩",
      "category": "concept"
    }
  ],
